"emGreeting": "އައްސަލާމު ޢަލައިކުމް {name},",
"emBody": "ތިބާ މިތަނަށް އައީމަ އަހަރު އެންމެ ހަނދާންވެރި. މާތް ﷲ ޤުރްއާން ތިބާގެ ހިތުގެ އަލި ކުރައްވާށި. މިހާރު ތިބާގެ ބަހުން ކިޔެވޭނެ، ހާސްގަނޑަށް ކިޔަވާލާބޭފުޅުންގެ ކިޔުން އަޑުއަހާލެވޭނެ، ކަމުދާ އާޔަތްތައް ސޭވްކުރެވޭނެ، އަދި އައު ކަމެއް ދަސްކުރަން އެދުން ވަގުތު އޭއައި ޝެއިޚަށް ސުވާލު އެހޭނެ.",
"emCta": "Tilawa ހުޅުވާ",
"emSign": "ލޯބިއާއެކު، Tilawa ޓީމް",
"emFriend": "ލޯބިވެރި ދޮންތަ",
"langLabel": "ބަސް",
"obSoon": "އެޕް ސެޓަޕް ނިމޭތަނާ ސައިންއަޕް ލިބޭނެ. މިހާރު ކިޔަން ފެށޭ.",
